//! The dapp registry a factory contract belongs to.
//!
//! A contract generated by `#[odra::module(factory = on)]` can join a dapp registry like any other
//! contract: it answers `get_dapp_registry`, which the registry calls to verify the contract points back
//! to it, and the holder of the factory access sets the registry with `set_factory_dapp_registry`.
//!
//! The factory shares its wasm with the contracts it deploys, so when the child module has its own
//! `get_dapp_registry`, both use one exported function: it returns the registry stored here if there is
//! one, and runs the child's function otherwise. The storage key cannot collide with a module field,
//! whose keys are hex encoded hashes.
use crate::prelude::*;
use crate::ContractEnv;

/// The storage key of the factory's dapp registry.
pub const DAPP_REGISTRY_KEY: &[u8] = b"__odra_factory_dapp_registry";
/// The entry point returning the dapp registry, the same as in the `DappContract` interface.
pub const GET_DAPP_REGISTRY: &str = "get_dapp_registry";
/// The entry point setting the factory's dapp registry; only the factory access holder may call it.
pub const SET_DAPP_REGISTRY: &str = "set_factory_dapp_registry";
/// The argument of [`SET_DAPP_REGISTRY`].
pub const REGISTRY_ARG: &str = "registry";

/// Returns the dapp registry stored in the factory, if any.
pub fn dapp_registry(env: &ContractEnv) -> Option<Address> {
    env.get_value(DAPP_REGISTRY_KEY)
}

/// Stores the factory's dapp registry and returns the previous one.
///
/// Reverts with [`ExecutionError::DappRegistryNotAContract`] if `registry` is not a contract.
pub fn set_dapp_registry(env: &ContractEnv, registry: Address) -> Option<Address> {
    if !registry.is_contract() {
        env.revert(ExecutionError::DappRegistryNotAContract);
    }
    let previous = dapp_registry(env);
    env.set_value(DAPP_REGISTRY_KEY, registry);
    previous
}
